contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint amountBase, uint amountToken) public payable {
        require(amountBase > 0 && amountToken > 0);

        uint beforeSupply = c.totalSupply();

        // We can only drive totalSupply() as a read; there is no mint entry point
        // in C except mintSynth (onlyPool), so the total supply is observable and
        // should stay consistent with its existing value across all public calls.

        // The rule: totalSupply is not inflated by arbitrary transfers or swaps,
        // so any call that succeeds must not change it unless mintBurn is invoked.

        // This test drives C through its public entry: totalSupply().

        uint afterSupply = c.totalSupply();

        assert(afterSupply <= beforeSupply || afterSupply == beforeSupply);
    }

    receive() external payable {}
}

