contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address member, uint amount, uint amount2) public {
        // Read the before-value the key whose debt mintSynth should increment.
        address pool = address(this);
        uint beforeDebt = c.getmapAddress_LPDebt(pool);

        // The public entry point that changes state: drive c.mintSynth.
        uint returnedAmount = c.mintSynth(member, amount);

        uint afterDebt = c.getmapAddress_LPDebt(pool);

        // General rule: minting adds exactly the minted amount to the pool's debt,
        // with no overflow within realistic input ranges.
        assert(afterDebt == beforeDebt + amount && returnedAmount == amount);
    }
}

