contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0) && recipient != address(this));
        require(amount > 0);

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(recipient);
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        if (senderBefore >= amount) {
            try c.transfer(recipient, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint256 senderAfter = c.balanceOf(address(this));
            uint256 recipientAfter = c.balanceOf(recipient);
            assert(!reverted && senderAfter == senderBefore - amount && recipientAfter == recipientBefore + amount && c.totalSupply() == supplyBefore);
        } else {
            try c.transfer(recipient, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted && c.balanceOf(address(this)) == senderBefore && c.balanceOf(recipient) == recipientBefore && c.totalSupply() == supplyBefore);
        }
    }

    receive() external payable {}
}

