contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address owner, address spender, uint256 amt1, uint256 amt2) public {
        require(owner != address(0), "owner zero");
        require(spender != address(0), "spender zero");

        // make owner the caller for approve, and read the pre-existing allowance
        uint256 before1 = c.allowance(owner, spender);
        bool ok1 = c.approve(spender, amt1);
        uint256 after1 = c.allowance(owner, spender);

        uint256 expected1 = (before1 < type(uint256).max) ? amt1 : before1;
        assert(after1 == expected1);

        // second approve must reflect the second amount in the same conditional manner
        uint256 before2 = c.allowance(owner, spender);
        bool ok2 = c.approve(spender, amt2);
        uint256 after2 = c.allowance(owner, spender);

        uint256 expected2 = (before2 < type(uint256).max) ? amt2 : before2;
        assert(after2 == expected2);
    }

    receive() external payable {}
}

