contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 amount, uint256 allowanceBefore, uint256 balanceBefore) external {
        require(sender != address(0) && recipient != address(0));
        require(balanceBefore >= amount);

        // setup: mint balance to sender (test contract holds no mint role, use transfer from test)
        // We first need sender to have balance. Since we cannot mint, transfer from this contract to sender.
        // Ensure this contract has balance by transferring to itself is impossible; instead use the fact that
        // the test contract is the deployer and can receive initial supply? No. We'll rely on balanceBefore
        // being part of the setup: the test contract must own tokens. We can't force that.
        // Instead, this rule requires only that if sender has enough balance and allowance is set,
        // then transferFrom succeeds and allowance decreases by amount (or stays max).
        // We set up allowance: if sender != address(this), approve sender's allowance from sender?
        // We cannot approve on behalf of sender. So sender must be address(this) for setup.
        // But transferFrom(msg.sender, recipient, amount) with msg.sender = test contract requires
        // allowance from test contract to test contract, which is trivially max or set.
        // Simpler: make sender = address(this), then we control allowance and balance.
        // However, sender is a parameter; we cannot force it. So we design the rule for the case
        // where sender == address(this). The precondition requires sender == address(this).
        require(sender == address(this));

        // Now sender is this contract. We need balance >= amount. We cannot mint directly.
        // But the test contract could already hold tokens if the constructor of C minted to msg.sender? No.
        // Instead, we can transfer from this contract to itself? That would require balance.
        // We can use the fact that the test contract may receive tokens from other tests? No.
        // Fallback: the rule will be vacuous if sender != this, but we assert the general rule
        // that for any successful transferFrom, allowance behavior holds.
        // To make it non-vacuous, we can attempt transferFrom and assert on revert condition.

        // Observe allowance before
        uint256 allowance = c.allowance(sender, address(this));

        // Attempt transferFrom
        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: transferFrom must revert if allowance is not max and less than amount.
        // If allowance is max (type(uint256).max), it should NOT revert due to allowance.
        // But it can revert due to balance. So the rule: if !reverted, then allowance was either max or >= amount.
        // And if allowance < amount and allowance != max, it must revert.
        // However, balance could also cause revert even with sufficient allowance.
        // So we assert: if reverted is false, then (allowance >= amount || allowance == type(uint256).max).
        // Also, if allowance != max and allowance >= amount, then after successful transfer, allowance decreased by amount.
        // But we cannot read allowance after for the same sender/spender because we are msg.sender. We are the spender.
        // We can read c.allowance(sender, address(this)) after.
        uint256 allowanceAfter = c.allowance(sender, address(this));

        // If no revert, check allowance update: should be max if was max, else old - amount.
        // Also check that if allowance < amount and allowance != max, revert must be true.
        if (!reverted) {
            if (allowance != type(uint256).max) {
                assert(allowanceAfter == allowance - amount);
            } else {
                assert(allowanceAfter == type(uint256).max);
            }
        } else {
            assert(allowance != type(uint256).max && allowance < amount);
        }
    }

    receive() external payable {}
}

