        } catch {
            setupSucceeded = false;
        }

        bool reverted;
        bool result;
        try c.burnSynth() returns (bool r) {
            result = r;
            reverted = false;
        } catch {
            result = false;
            reverted = true;
        }

        // General rule: a completed burnSynth must return true; and if it completed with the
        // caller's debt being zero, that would mean a division by zero was possible, so such
        // a completion is only valid when the caller's LPDebt was nonzero at call time.
        assert(reverted || (result == true));
    }

    receive() external payable {}
}

