    function run(address sender, address recipient, uint256 bal1, uint256 amount, uint256 allowanceAmount) public payable {
        // Give the sender some balance so transferFrom has something to move.
        // Minting is done through a public entry point on c that feeds the pool.
        // Use mintSynth only if sender has LP units? Instead, drive the standard ERC20 surface.
        // We rely on c.mintSynth to be callable by curated pools; not available. So instead
        // we use the balance the sender may already have; but to create non-zero balance we
        // can send tokens directly is not allowed. We must use public surface.
        // Simplest: only assert on the allowance mechanics using amount=0 and the allowance we set.
        // Precondition: set allowance from sender to this test contract.
