        c.approve(address(this), allowanceAmount);

        bool reverted;
        try c.transferFrom(address(this), recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if allowance was set to max, transferFrom must not revert from allowance checks,
        // but may revert from balance. If balance is zero and amount > 0, it must revert.
        // We can observe balanceOf(address(this)) before and after.
        uint256 beforeBal = c.balanceOf(address(this));
        uint256 beforeAllowance = c.allowance(address(this), address(this));

        // Re-check after
        uint256 afterBal = c.balanceOf(address(this));
        uint256 afterAllowance = c.allowance(address(this), address(this));

        // Rule: transferFrom must either move amount and reduce allowance (if not max), or revert.
        // Specifically: if it did not revert, then afterBal == beforeBal - amount OR beforeBal >= amount.
        // Also allowance was either max (unchanged) or reduced by amount.
        assert(
            reverted ||
            ((beforeAllowance == type(uint256).max || afterAllowance == beforeAllowance - amount) &&
             afterBal == beforeBal - amount)
        );
    }

