contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address pool, uint256 synthAmount) public {
        // Ensure the caller (this test contract) has a nonzero LP debt at the pool.
        // mintSynth is onlyPool; we cannot call it directly. However, the rule is
        // about burnSynth's effect on mapSynth_LPBalance[key]. We drive burnSynth
        // through the public entry point and check that any LP balance key is
        // non-increasing and that the caller's key changes by at most the
        // synthesized amount supplied to the contract.

        uint256 beforeCallerLP = c.getmapAddress_LPBalance(address(this));
        uint256 beforeCallerDebt = c.getmapAddress_LPDebt(address(this));
        uint256 beforeSupply = c.totalSupply();
        uint256 beforePoolLP = c.getmapAddress_LPBalance(pool);
        uint256 beforePoolDebt = c.getmapAddress_LPDebt(pool);

        bool reverted;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCallerLP = c.getmapAddress_LPBalance(address(this));
        uint256 afterCallerDebt = c.getmapAddress_LPDebt(address(this));
        uint256 afterSupply = c.totalSupply();
        uint256 afterPoolLP = c.getmapAddress_LPBalance(pool);
        uint256 afterPoolDebt = c.getmapAddress_LPDebt(pool);

        // General rule: burnSynth never increases any address's LP balance/debt;
        // if it does not revert and the caller had no debt, nothing changes at all.
        if (!reverted && beforeCallerDebt == 0) {
            assert(afterCallerLP == beforeCallerLP);
            assert(afterCallerDebt == beforeCallerDebt);
            assert(afterSupply == beforeSupply);
        } else {
            assert(afterCallerLP <= beforeCallerLP);
            assert(afterCallerDebt <= beforeCallerDebt);
            assert(afterSupply <= beforeSupply);
            assert(afterPoolLP <= beforePoolLP);
            assert(afterPoolDebt <= beforePoolDebt);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address pool, uint256 synthAmount) public {
        // Drive c through a public state-changing call so burnSynth has a defined surface.
        // Mint a synthetic amount to this test contract via the public mintSynth entry if possible;
        // otherwise use whatever balance is already present. mintSynth is onlyPool, so we
        // attempt it with a caller-supplied pool and gracefully ignore failure by using try/catch
        // is not allowed; instead we simply use the public burnSynth entry directly.

        // Precondition: caller must have no debt so the expected change is deterministic
        // (debt == 0 means burnSynth should leave LP balance unchanged).
        // We cannot enforce that here; we read before-values, call burnSynth, and assert the
        // general ratio rule for the caller's key.

        uint256 beforeCallerLP = c.getmapAddress_LPBalance(address(this));
        uint256 beforeCallerDebt = c.getmapAddress_LPDebt(address(this));
        uint256 beforeSupply = c.totalSupply();

        bool reverted = false;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCallerLP = c.getmapAddress_LPBalance(address(this));
        uint256 afterCallerDebt = c.getmapAddress_LPDebt(address(this));
        uint256 afterSupply = c.totalSupply();

        // General rule: after burnSynth, the caller's LP balance can only decrease or stay the same,
        // the caller's LP debt can only decrease or stay the same, and totalSupply can only decrease
        // or stay the same. When the caller had no debt, LP balance and debt are unchanged.
        assert(
            (beforeCallerDebt == 0 && afterCallerLP == beforeCallerLP && afterCallerDebt == beforeCallerDebt)
            ||
            (afterCallerLP <= beforeCallerLP && afterCallerDebt <= beforeCallerDebt && afterSupply <= beforeSupply)
        );
    }

    receive() external payable {}
}

