contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address pool, uint256 amount) public payable {
        // Record the caller's debt balance before the call.
        uint256 debtBefore = c.getmapAddress_LPDebt(pool);

        // Try the burnSynth call. A revert is allowed because the contract may
        // not have enough synthetic balance or the pool may not have LP debt yet.
        bool reverted;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the caller's debt balance after the call.
        uint256 debtAfter = c.getmapAddress_LPDebt(pool);

        // The general rule: if burnSynth succeeds, the caller's recorded synthetic
        // debt must not increase (it can only stay the same or decrease).
        // This must hold for every possible pool key and every possible input amount.
        if (!reverted) {
            assert(debtAfter <= debtBefore);
        }
    }

    receive() external payable {}
}

