contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public {
        require(to != address(0), "recipient zero");
        uint256 balBeforeSender = c.balanceOf(address(this));
        uint256 balBeforeTo = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();
        // pre-state is not required to be rich; the rule is conditional on a successful call
        // Give the test contract `amount` units out of thin air is impossible without mint
        // So we use the current balance and only assert on success. If sender lacks balance the call reverts.
        bool reverted;
        try c.transfer(to, amount) { reverted = false; } catch { reverted = true; }
        if (!reverted) {
            uint256 balAfterSender = c.balanceOf(address(this));
            uint256 balAfterTo = c.balanceOf(to);
            uint256 supplyAfter = c.totalSupply();
            assert(balAfterSender + amount == balBeforeSender);
            assert(balAfterTo == balBeforeTo + amount);
            assert(supplyAfter == supplyBefore);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

